<?php
require_once 'config.php';
$id = (int) ($_GET['id'] ?? 0);
$product = null; $related = []; $reviews = [];
try {
    $stmt = db()->prepare('SELECT p.*, c.name category FROM products p JOIN categories c ON c.id=p.category_id WHERE p.id=?');
    $stmt->execute([$id]); $product = $stmt->fetch();
    if (!$product) redirect('shop.php');
    $stmt = db()->prepare('SELECT * FROM products WHERE category_id=? AND id<>? ORDER BY featured DESC LIMIT 4');
    $stmt->execute([$product['category_id'], $id]); $related = $stmt->fetchAll();
    $stmt = db()->prepare('SELECT r.*, u.full_name FROM reviews r JOIN users u ON u.id=r.user_id WHERE r.product_id=? ORDER BY r.created_at DESC');
    $stmt->execute([$id]); $reviews = $stmt->fetchAll();
} catch (Throwable $exception) { redirect('shop.php'); }
$pageTitle = $product['name']; include 'includes/header.php';
?>
<section class="section product-detail"><div class="container"><div class="product-detail-grid"><div><div class="gallery-main" id="gallery-main"><img id="main-product-image" src="<?= e($product['image'] ?: 'https://images.unsplash.com/photo-1582722872445-44dc5f7e3c8f?auto=format&fit=crop&w=1000&q=85') ?>" alt="<?= e($product['name']) ?>" width="900" height="700"></div><div class="gallery-thumbs"><button data-gallery-image="<?= e($product['image'] ?: 'https://images.unsplash.com/photo-1582722872445-44dc5f7e3c8f?auto=format&fit=crop&w=1000&q=85') ?>"><img src="<?= e($product['image'] ?: 'https://images.unsplash.com/photo-1582722872445-44dc5f7e3c8f?auto=format&fit=crop&w=220&q=80') ?>" alt="Front view" width="120" height="90" loading="lazy"></button><button data-gallery-image="https://images.unsplash.com/photo-1569288063643-5d29ad64dfb5?auto=format&fit=crop&w=1000&q=85"><img src="https://images.unsplash.com/photo-1569288063643-5d29ad64dfb5?auto=format&fit=crop&w=220&q=80" alt="Farm view" width="120" height="90" loading="lazy"></button><button data-gallery-image="https://images.unsplash.com/photo-1516467508483-a7212febe31a?auto=format&fit=crop&w=1000&q=85"><img src="https://images.unsplash.com/photo-1516467508483-a7212febe31a?auto=format&fit=crop&w=220&q=80" alt="Poultry view" width="120" height="90" loading="lazy"></button></div></div><div class="product-detail-copy"><div class="eyebrow"><?= e($product['category']) ?></div><h1><?= e($product['name']) ?></h1><div class="rating">★★★★★ <span><?= e((string)$product['rating']) ?> · <?= count($reviews) ?> reviews</span></div><p class="detail-price"><?= money($product['price']) ?></p><p><?= e($product['description']) ?></p><div class="stock-message <?= $product['stock'] <= LOW_STOCK_THRESHOLD ? 'low-stock' : '' ?>"><?= e(stock_message((int)$product['stock'])) ?></div><?php if ($product['stock'] > 0): ?><button class="btn btn-primary" data-add-cart="<?= (int)$product['id'] ?>" data-csrf="<?= e(csrf_token()) ?>">Add to cart →</button><?php else: ?><button class="btn btn-outline" disabled>Currently unavailable</button><?php endif; ?><div class="trust-row"><span>✓ Secure checkout</span><span>✓ Farm quality promise</span><span>✓ Local delivery</span></div></div></div><section class="section related-section"><div class="section-heading"><div><div class="eyebrow">Keep browsing</div><h2>You may also like.</h2></div></div><div class="product-grid"><?php foreach ($related as $item): ?><a class="product-card" href="product.php?id=<?= (int)$item['id'] ?>"><div class="product-image eggs"><span class="badge">View product</span></div><div class="product-info"><h3><?= e($item['name']) ?></h3><div class="product-meta"><span class="price"><?= money($item['price']) ?></span><span class="text-link">Details →</span></div></div></a><?php endforeach; ?></div></section><section class="review-section"><div class="section-heading"><div><div class="eyebrow">Customer notes</div><h2>Reviews.</h2></div></div><?php if (!$reviews): ?><div class="empty-state"><div class="empty-icon">♡</div><h3>No reviews yet</h3><p>Be the first customer to share your experience.</p></div><?php else: ?><div class="testimonial-grid"><?php foreach ($reviews as $review): ?><article class="testimonial"><div class="rating"><?= str_repeat('★', (int)$review['rating']) ?></div><p><?= e($review['comment']) ?></p><strong><?= e($review['full_name']) ?></strong></article><?php endforeach; ?></div><?php endif; ?></section></div></section>
